import io as _io, contextlib as _cl
def _out(fn, *a, **k):
    buf = _io.StringIO()
    with _cl.redirect_stdout(buf):
        fn(*a, **k)
    return buf.getvalue()
def _raises(fn, *a, **k):
    try:
        fn(*a, **k)
    except Exception as e:
        return type(e).__name__
    return None
def _error(fn, *a, **k):
    try:
        fn(*a, **k)
    except Exception as e:
        return f"{type(e).__name__}: {e}"
    return None
def _logs(fn, *a, **k):
    import logging as _lg
    records = []
    class _H(_lg.Handler):
        def emit(self, r):
            records.append(f"{r.levelname}: {r.getMessage()}")
    h = _H()
    root = _lg.getLogger()
    old = root.level
    root.addHandler(h)
    root.setLevel(_lg.DEBUG)
    try:
        fn(*a, **k)
    finally:
        root.removeHandler(h)
        root.setLevel(old)
    return records
def _raise(exc):
    raise exc
def _catches(test_fn, name, fake):
    g = test_fn.__globals__
    real = g[name]
    g[name] = fake
    try:
        test_fn()
    except AssertionError:
        return True
    finally:
        g[name] = real
    return False

