import json
import random

def masked(word, guessed):
    return " ".join(letter if letter in guessed else "_" for letter in word)


def is_solved(word, guessed):
    return all(letter in guessed for letter in word)


def check_guess(text):
    letter = text.strip().lower()
    if len(letter) != 1:
        raise ValueError("Type one letter")
    if not letter.isalpha():
        raise ValueError("Letters only")
    return letter


def apply_guess(word, guessed, letter):
    if letter in guessed:
        return f"You already tried {letter}"
    guessed.add(letter)
    if letter in word:
        return "Good guess!"
    return f"No {letter} in the word"


def wrong_letters(word, guessed):
    return sorted(letter for letter in guessed if letter not in word)


def lives_left(word, guessed, max_wrong=6):
    return max_wrong - len(wrong_letters(word, guessed))


def status(word, guessed, max_wrong=6):
    wrong = ", ".join(wrong_letters(word, guessed)) or "none"
    return f"{masked(word, guessed)}   Lives: {lives_left(word, guessed, max_wrong)}   Wrong: {wrong}"


def pick_word(words, seed=None):
    return random.Random(seed).choice(words)


def play(word, guesses, max_wrong=6):
    guessed = set()
    lines = []
    for raw in guesses:
        try:
            letter = check_guess(raw)
        except ValueError as e:
            lines.append(str(e))
            continue
        lines.append(apply_guess(word, guessed, letter))
        if is_solved(word, guessed):
            lines.append(f"You win! The word was {word}")
            return lines
        if lives_left(word, guessed, max_wrong) <= 0:
            lines.append(f"Out of lives! The word was {word}")
            return lines
    lines.append("Game not finished")
    return lines

