def run(budget, commands):
    output = []
    for command in commands:
        words = command.split()
        try:
            if not words:
                continue
            if words[0] == "add" and len(words) >= 5:
                day, amount, category = words[1], parse_amount(words[2]), words[3]
                try:
                    date.fromisoformat(day)
                except ValueError:
                    raise ValueError(f"Bad date: {day}")
                description = " ".join(words[4:])
                budget.add(Transaction(day, description, amount, category))
                output.append(f"Added: {description} ({amount:.2f})")
            elif words[0] == "limit" and len(words) == 3:
                amount = parse_amount(words[2])
                budget.set_limit(words[1], amount)
                output.append(f"Limit for {words[1]}: {amount:.2f}")
            elif words[0] == "balance":
                output.append(f"Balance: {budget.balance():.2f}")
            elif words[0] == "report" and len(words) == 2:
                output.extend(budget.report(words[1]))
            else:
                output.append("Commands: add DATE AMOUNT CATEGORY TEXT, limit CATEGORY AMOUNT, balance, report YYYY-MM")
        except ValueError as e:
            output.append(str(e))
    return output

