        verb, noun = parse(command)
        player = self.player
        if verb == "look":
            return self.view()
        if verb == "go":
            try:
                player.move(noun)
            except ValueError as e:
                return str(e)
            return self.view()
        if verb == "take":
            if not self.can_see():
                return "It is too dark to find anything."
            reply = player.take(noun)
            if find(player.inventory, "treasure"):
                self.over = True
                reply += "\nYou found the treasure! You win!"
            return reply
        if verb == "drop":
            return player.drop(noun)
        if verb == "use":
            return player.use(noun)
        if verb == "inventory":
            return "You carry: " + (", ".join(item.name for item in player.inventory) or "nothing")
        if verb == "examine":
            item = find(player.inventory + player.room.items, noun)
            return item.description if item else f"You see no {noun} here."
        if verb == "quit":
            self.over = True
            return "Goodbye!"
        return "I don't understand that."

    def save(self, path):
        state = {
            "room": self.player.room.name,
            "inventory": [item.name for item in self.player.inventory],
            "items": {name: [item.name for item in room.items] for name, room in self.rooms.items()},
            "locked": {name: room.locked for name, room in self.rooms.items()},
        }
        with open(path, "w", encoding="utf-8") as f:
            json.dump(state, f, indent=2)

    @classmethod
    def load(cls, path):
        with open(path, encoding="utf-8") as f:
            state = json.load(f)
        game = cls()
        every_item = {item.name: item for room in game.rooms.values() for item in room.items}
        for name, room in game.rooms.items():
            room.items = [every_item[n] for n in state["items"][name]]
            room.locked = state["locked"][name]
        game.player.inventory = [every_item[n] for n in state["inventory"]]
        game.player.room = game.rooms[state["room"]]
        return game


def play(commands):
    game = Game()
    replies = []
    for command in commands:
        replies.append(game.handle(command))
        if game.over:
            break
    return replies

