import json
import shlex
from dataclasses import dataclass, asdict
from pathlib import Path


@dataclass
class Book:
    title: str
    author: str
    pages: int
    pages_read: int = 0

    @property
    def finished(self):
        return self.pages_read >= self.pages


def progress(pages_read: int, pages: int) -> int:
    """Return how far through a book you are, as a whole percentage from 0 to 100."""
    if pages <= 0:
        return 0
    return min(100, pages_read * 100 // pages)


def test_progress():
    assert progress(0, 400) == 0
    assert progress(100, 400) == 25
    assert progress(399, 400) == 99
    assert progress(500, 400) == 100
    assert progress(10, 0) == 0


def add_book(log, title, author, pages):
    title, author = title.strip(), author.strip()
    if not title or not author:
        raise ValueError("A book needs a title and an author")
    if pages <= 0:
        raise ValueError("Pages must be more than 0")
    if any(book.title.lower() == title.lower() for book in log):
        raise ValueError(f"{title} is already in your log")
    book = Book(title, author, pages)
    log.append(book)
    return book


def parse_command(text):
    try:
        words = shlex.split(text)
    except ValueError:
        raise ValueError("Check your quotes")
    if not words:
        raise ValueError("Type a command")
    return words[0].lower(), words[1:]


def save_log(log, path):
    with open(path, "w", encoding="utf-8") as f:
        json.dump([asdict(book) for book in log], f, indent=2)


def load_log(path):
    try:
        with open(path, encoding="utf-8") as f:
            return [Book(**data) for data in json.load(f)]
    except FileNotFoundError:
        return []


def create_project(root, files):
    created = []
    for name, text in files.items():
        path = Path(root) / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
        created.append(path.as_posix())
    return sorted(created)


def make_readme(name, description, features, command):
    lines = [f"# {name}", "", description, "", "## Features", ""]
    lines += [f"- {feature}" for feature in features]
    lines += ["", "## How to run it", "", "```", command, "```", ""]
    return "\n".join(lines)


def run_tests(namespace):
    passed, failed = [], []
    for name in sorted(namespace):
        test = namespace[name]
        if name.startswith("test_") and callable(test):
            try:
                test()
            except AssertionError:
                failed.append(name)
            else:
                passed.append(name)
    return passed, failed


def main(args, path="books.json"):
    log = load_log(path)
    try:
        if not args:
            raise ValueError("Commands: add TITLE AUTHOR PAGES, read TITLE PAGES, list")
        command, rest = args[0], args[1:]
        if command == "add" and len(rest) == 3:
            book = add_book(log, rest[0], rest[1], int(rest[2]))
            print(f"Added {book.title}")
        elif command == "read" and len(rest) == 2:
            book = next((b for b in log if b.title.lower() == rest[0].lower()), None)
            if book is None:
                raise ValueError(f"No book called {rest[0]}")
            book.pages_read = min(book.pages, book.pages_read + int(rest[1]))
            print(f"{book.title}: {progress(book.pages_read, book.pages)}%")
        elif command == "list":
            for book in log:
                mark = "done" if book.finished else f"{progress(book.pages_read, book.pages)}%"
                print(f"{book.title} by {book.author} ({mark})")
        else:
            raise ValueError("Commands: add TITLE AUTHOR PAGES, read TITLE PAGES, list")
    except ValueError as e:
        print(e)
        return 1
    save_log(log, path)
    return 0

