import io as _io, contextlib as _cl
def _out(fn, *a, **k):
    buf = _io.StringIO()
    with _cl.redirect_stdout(buf):
        fn(*a, **k)
    return buf.getvalue()
def _raises(fn, *a, **k):
    try:
        fn(*a, **k)
    except Exception as e:
        return type(e).__name__
    return None
